-- PRD 4.5, 6 — reviewed overseas custody is intentional exclusion, not a failed match.
-- Version aligned with the migration generated by Supabase on production.
-- No new found_items columns; raw API fields and normal retention remain unchanged.
set local lock_timeout = '5s';
set local statement_timeout = '60s';

alter table public.found_items drop constraint found_items_location_match_status_check;
alter table public.found_items add constraint found_items_location_match_status_check
    check (location_match_status in ('matched','unmatched','ambiguous','excluded_overseas'));
alter table public.found_items drop constraint found_items_location_match_consistent;
alter table public.found_items add constraint found_items_location_match_consistent check (
    (location_match_status = 'matched' and storage_location_id is not null)
    or (location_match_status in ('unmatched','ambiguous','excluded_overseas') and storage_location_id is null)
);

create function public.is_overseas_custody(source_code text, custody_name text)
returns boolean language sql immutable parallel safe security invoker set search_path = '' as $$
    select coalesce(source_code = 'partner_api' and pg_catalog.regexp_replace(
        pg_catalog.lower(pg_catalog.normalize(custody_name,'NFKC')), '[^[:alnum:]]','','g') in (
        '주타이베이대한민국대표부',
        '주오스트리아대사관',
        '주홍콩대한민국총영사관',
        '주이탈리아대한민국대사관',
        '주바르셀로나총영사관',
        '주덴마크대사관',
        '주체코대사관',
        '주헝가리대한민국대사관',
        '주스페인대사관',
        '주스위스대한민국대사관',
        '주고베총영사관',
        '주삿포로총영사관',
        '주독일대사관'
    ), false);
$$;
revoke all on function public.is_overseas_custody(text,text) from public,anon,authenticated;
grant execute on function public.is_overseas_custody(text,text) to service_role;

create function public.exclude_overseas_custody()
returns trigger language plpgsql security invoker set search_path = '' as $$
declare
    custody text;
    target_id bigint;
begin
    -- Runs after the existing resolver has restored valid detail or cleared stale detail.
    custody := case when new.detail_checked_at is not null
        then coalesce(nullif(pg_catalog.btrim(new.detail_department),''),new.raw_storage_name)
        else new.raw_storage_name end;
    if public.is_overseas_custody(new.item_source_code,custody) then
        new.location_match_status := 'excluded_overseas';
        new.storage_location_id := null;
    elsif new.location_match_status = 'excluded_overseas' then
        -- A domestic current custody must not stay excluded because its historical raw name was overseas.
        select m.storage_location_id into target_id
        from public.storage_location_detail_mappings m
        join public.storage_locations l on l.id=m.storage_location_id and l.is_active
        where m.item_source_code=new.item_source_code and m.detail_org_id=new.detail_org_id
          and m.normalized_raw_storage_name=pg_catalog.regexp_replace(
              pg_catalog.lower(pg_catalog.normalize(new.detail_department,'NFKC')), '[^[:alnum:]]','','g')
          and new.detail_checked_at is not null
          and l.location_source_code=case new.item_source_code
              when 'police_api' then 'esri_police' when 'partner_api' then 'partner_csv' end;
        new.storage_location_id := target_id;
        new.location_match_status := case when target_id is null then 'unmatched' else 'matched' end;
    end if;
    return new;
end;
$$;
revoke all on function public.exclude_overseas_custody() from public,anon,authenticated;
grant execute on function public.exclude_overseas_custody() to service_role;

-- PostgreSQL fires same-kind triggers by name; preserve the existing resolver's execution first.
create trigger found_items_zz_exclude_overseas
    before insert or update on public.found_items
    for each row execute function public.exclude_overseas_custody();

-- Identity-independent backfill; current reviewed detail takes precedence over historical raw custody.
update public.found_items set location_match_status='excluded_overseas',storage_location_id=null
where location_match_status <> 'excluded_overseas'
  and public.is_overseas_custody(item_source_code,
      case when detail_checked_at is not null
          then coalesce(nullif(pg_catalog.btrim(detail_department),''),raw_storage_name)
          else raw_storage_name end);

notify pgrst, 'reload schema';
